// ===== CONFIGURACIÓN DE LABORATORIO (editar antes de activar) =====
// Todos los correos van a este destinatario de prueba, NO al paciente: los datos del laboratorio son sintéticos.
const LAB_RECIPIENT = 'LAB_RECIPIENT_AQUI';
// ====================================================================
const API_BASE_URL = 'API_BASE_URL_AQUI';
if (LAB_RECIPIENT === 'LAB_RECIPIENT_AQUI' || API_BASE_URL === 'API_BASE_URL_AQUI') {
  throw new Error('Configura LAB_RECIPIENT y API_BASE_URL antes de ejecutar');
}
return [{ json: { apiBaseUrl: API_BASE_URL, labRecipient: LAB_RECIPIENT, fecha: $now.toFormat('yyyy-MM-dd') } }];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const cfg = $('Calcular fecha').first().json;
const r = $input.first().json;
const tabla = (titulo, mapa) => '<h3>' + titulo + '</h3><table border="1" cellpadding="4" style="border-collapse:collapse"><tr><th>Grupo</th><th>Citas</th></tr>'
  + Object.entries(mapa ?? {}).map(([k, v]) => '<tr><td>' + esc(k) + '</td><td>' + esc(v) + '</td></tr>').join('') + '</table>';
const html = '<h2>Resumen operativo ' + esc(r.fecha ?? cfg.fecha) + '</h2><p>Total de citas: <b>' + esc(r.total ?? 0) + '</b></p>'
  + tabla('Por sede', r.porSede) + tabla('Por estado', r.porEstado) + tabla('Por especialidad', r.porEspecialidad)
  + '<p style="color:#666">Resumen agregado, sin datos personales. Laboratorio FCV.</p>';
return [{ json: { to: cfg.labRecipient, subject: '[FCV Lab] Resumen operativo ' + (r.fecha ?? cfg.fecha), html } }];

const cfg = $('Calcular fecha').first().json;
return [{ json: { to: cfg.labRecipient, subject: '[FCV Lab] INCIDENCIA: no se pudo generar el resumen del ' + cfg.fecha,
  html: '<p>La API de citas no respondió al consultar el resumen del día ' + cfg.fecha + '. Revisa que citas-api y el túnel estén activos.</p>' } }];
